// Transformação Bronze → Gold conforme regras de negócio
// DECISÃO: Nomes em PT, campos calculados (duração, categoria, flags)
const items = $input.all();
const now = new Date().toISOString();

const statusMap = {
  'PROCESSING': 'EM_PROCESSAMENTO',
  'COMPLETED': 'CONCLUIDO',
  'FAILED': 'FALHOU',
  'CANCELED': 'CANCELADO'
};

const tipoMap = { 'PERSON': 'PESSOA', 'COMPANY': 'EMPRESA' };

function categoria(total) {
  if (total <= 100) return 'PEQUENO';
  if (total <= 500) return 'MEDIO';
  if (total <= 1500) return 'GRANDE';
  return 'MUITO_GRANDE';
}

return items.map(({ json }) => {
  const created = new Date(json.created_at);
  const updated = new Date(json.updated_at);
  const duracaoMin = (updated - created) / 60000;
  const total = json.total_contacts || 1;
  const tempoPorContato = total > 0 ? duracaoMin / total : 0;
  const success = json.status === 'COMPLETED';
  const reprocessar = ['FAILED', 'PROCESSING'].includes(json.status);

  return {
    json: {
      id_enriquecimento: json.id,
      id_workspace: json.id_workspace,
      nome_workspace: json.workspace_name,
      total_contatos: json.total_contacts,
      tipo_contato: tipoMap[json.contact_type] || json.contact_type,
      status_processamento: statusMap[json.status] || json.status,
      data_criacao: json.created_at,
      data_atualizacao: json.updated_at,
      duracao_processamento_minutos: duracaoMin,
      tempo_por_contato_minutos: tempoPorContato,
      processamento_sucesso: success,
      categoria_tamanho_job: categoria(json.total_contacts),
      necessita_reprocessamento: reprocessar,
      data_atualizacao_dw: now
    }
  };
});
